// #ebdb2f (6a993d7890d7492f45ebdb2f) «פיתוח: ניהול פרטי העסק והעדפותיו על ידי מנהל החשבון» (F-10, S-06). Кейсы BSET-001…BSET-004.
// Роль: business (testim, сохранённая сессия .qa/auth/business.json, без пароля). Только десктоп (L-20261014-5).
//  - BSET-001 экран и квота (только чтение)                                  → @prod-safe
//  - BSET-002 пустое «שם העסק» / «תפקיד איש הקשר» блокирует сохранение      → @prod-safe (PATCH businesses перехватывается и обрывается)
//  - BSET-003 изоляция: чужой бизнес не читается, PATCH чужого → 0 строк    → только чтение + PATCH чужого id (имя = его же имя, т.е. даже при утечке ничего не меняется)
//  - BSET-004 he → en: сохранение, «פרטי העסק נשמרו», новая симуляция на английском, активные — без изменений
//             → @data: язык общего бизнеса testim на время теста = en; в finally язык ВСЕГДА возвращается к исходному (API той же сессии).
//               Не запускать одновременно с тестами, создающими симуляции (simulation-editor ждёт he).
import * as path from 'path';
import { Page } from '@playwright/test';
import { test, expect } from '@playwright/test';
import { openWithApi, Api } from '../support/api';

test.use({ storageState: path.resolve(__dirname, '../../../auth/business.json') });

const TAG = '#ebdb2f · #6a993d7890d7492f45ebdb2f';
const URL = '/settings/business';
// Чужой бизнес для проверки изоляции: QA-PILOT-1410 (решение/факт проверки 22.10).
const FOREIGN_ID = process.env.QA_EBDB2F_FOREIGN_ID || 'b0d2a797-4d78-4a74-83d1-c0c1bfc8a6a9';
const FOREIGN_NAME = process.env.QA_EBDB2F_FOREIGN_NAME || 'QA-PILOT-1410';

type Biz = { id: string; name: string; default_language: string; contact_role: string | null };
type Usage = { used: number; quota: number | null; remaining: number | null };

/** Открыть /settings/business, дождаться формы; вернуть API той же сессии и строку своего бизнеса. */
async function openSettings(page: Page): Promise<{ api: Api; biz: Biz }> {
  const api = await openWithApi(page, URL);
  await expect(page.getByRole('heading', { name: 'הגדרות העסק' }).first()).toBeVisible();
  await expect(page.getByRole('textbox', { name: 'שם העסק', exact: true })).toBeVisible();
  const res = await api.get('businesses?select=id,name,default_language,contact_role');
  expect(res.status(), await res.text()).toBe(200);
  const rows = (await res.json()) as Biz[];
  // RLS: менеджер видит только свой бизнес (треб. «רק העסק שלו»).
  expect(rows, 'businesses без фильтра — ровно одна (своя) строка').toHaveLength(1);
  return { api, biz: rows[0] };
}

const languageSelect = (page: Page) => page.getByLabel('שפת ברירת מחדל');
const saveButton = (page: Page) => page.getByRole('button', { name: 'שמירת שינויים' });

test.describe(`Настройки бизнеса — מנהל חשבון (${TAG})`, () => {
  test(`BSET-001: поля с текущими значениями, язык he=עברית / en=אנגלית, блок квоты (без квоты — «לא הוגדרה מכסה…» и число «נוצלו») @desktop @prod-safe ${TAG}`, async ({ page }) => {
    const { api, biz } = await openSettings(page);

    await expect(page.getByRole('textbox', { name: 'שם העסק', exact: true })).toHaveValue(biz.name);
    await expect(page.getByLabel(/^תפקיד איש הקשר/)).toHaveValue(biz.contact_role ?? '');

    // Источник: AC2 / требование «עברית כברירת מחדל» + факт 22.10 — опции he=עברית, en=אנגלית.
    const lang = languageSelect(page);
    await expect(lang).toBeEnabled();
    await expect(lang).toHaveValue(biz.default_language);
    const opts = await lang.locator('option').evaluateAll((o) => (o as HTMLOptionElement[]).map((x) => [x.value, x.textContent?.trim()]));
    expect(opts).toEqual([
      ['he', 'עברית'],
      ['en', 'אנגלית'],
    ]);

    // Источник: AC3 + S-06 пусто «ללא מכסה מוגדרת מוצג רק נתון הצריכה ללא חסימה».
    const u = await api.rpc('get_business_usage');
    expect(u.status(), await u.text()).toBe(200);
    const uj = await u.json();
    const usage = (Array.isArray(uj) ? uj[0] : uj) as Usage;
    const card = page.getByTestId('quota-card');
    await expect(card).toBeVisible();
    await expect(card.getByRole('heading', { name: /^מכסת סימולציות/ })).toBeVisible();
    await expect(card.getByTestId('quota-used')).toHaveText(new Intl.NumberFormat('he-IL').format(usage.used));
    if (usage.quota === null) {
      await expect(card.getByText('נוצלו', { exact: true })).toBeVisible();
      await expect(card.getByText(/^לא הוגדרה מכסה לחשבון, ולכן אין חסימה\. הצריכה נספרת/)).toBeVisible();
    } else {
      // Квота задана Super Admin: «נוצלו מתוך N» и остаток (AC3 «המכסה, הצריכה עד כה והיתרה»).
      await expect(card.getByText(`נוצלו מתוך ${new Intl.NumberFormat('he-IL').format(usage.quota)}`)).toBeVisible();
      await expect(card.getByText(/לא הוגדרה מכסה/)).toHaveCount(0);
      test.info().annotations.push({ type: 'quota', description: `квота задана: ${usage.used}/${usage.quota}` });
    }
    // R-02: размер квоты менеджер не меняет — полей квоты на экране нет.
    await expect(card.getByRole('spinbutton')).toHaveCount(0);
  });

  for (const f of [
    { label: 'שם העסק', locate: (p: Page) => p.getByRole('textbox', { name: 'שם העסק', exact: true }), error: 'יש להזין את שם העסק' },
    { label: 'תפקיד איש הקשר', locate: (p: Page) => p.getByLabel(/^תפקיד איש הקשר/), error: 'יש להזין את תפקיד איש הקשר' },
  ]) {
    test(`BSET-002: пустое «${f.label}» → сохранение заблокировано, ошибка у поля, остальные значения на месте, PATCH не уходит @desktop @prod-safe ${TAG}`, async ({ page }) => {
      let patches = 0;
      await page.route('**/rest/v1/businesses**', (route) => {
        if (route.request().method() !== 'PATCH') return route.continue();
        patches++;
        return route.abort();
      });
      await openSettings(page);

      const fields = page.locator('form input[id^="settings-"], form select[id^="settings-"]');
      const before = await fields.evaluateAll((els) => (els as HTMLInputElement[]).map((e) => [e.id, e.value]));
      expect(before.length, 'поля формы settings-*').toBeGreaterThanOrEqual(7);

      const target = f.locate(page);
      const targetId = await target.getAttribute('id');
      await target.fill('');
      await saveButton(page).click();

      // Источник: AC5 «השמירה נחסמת והשגיאה מוצגת ליד השדה תוך שמירת שאר הערכים»; context 14.10 — роль обязательна и в S-06.
      const alert = page.getByRole('alert').filter({ hasText: 'השינויים לא נשמרו' });
      await expect(alert).toBeVisible();
      await expect(alert).toContainText('חסרים פרטים בטופס. השדות המסומנים דורשים תיקון.');
      await expect(target).toHaveAttribute('aria-invalid', 'true');
      await expect(target).toHaveAccessibleDescription(f.error);
      await expect(target).toBeFocused();

      const after = await fields.evaluateAll((els) => (els as HTMLInputElement[]).map((e) => [e.id, e.value]));
      expect(after.filter(([id]) => id !== targetId)).toEqual(before.filter(([id]) => id !== targetId));
      await expect(page.locator('form [aria-invalid="true"]')).toHaveCount(1);

      await expect(page).toHaveURL(new RegExp(`${URL}$`));
      expect(patches, 'PATCH businesses не отправляется').toBe(0);
    });
  }

  test(`BSET-003: изоляция — чужой бизнес не читается (GET → []), PATCH чужого id → 200 и 0 строк @desktop ${TAG}`, async ({ page }) => {
    const { api, biz } = await openSettings(page);
    expect(biz.id).not.toBe(FOREIGN_ID);

    // Источник: треб. «מנהל החשבון רשאי לעדכן רק את העסק שלו» (F-10) — факт 22.10.
    const get = await api.get(`businesses?select=id,name&id=eq.${FOREIGN_ID}`);
    expect(get.status(), await get.text()).toBe(200);
    expect(await get.json()).toEqual([]);

    // Тело — текущее имя чужого бизнеса: даже если изоляция сломана, данные не меняются, а тест падает (вернётся 1 строка).
    const patch = await api.patch(`businesses?id=eq.${FOREIGN_ID}&select=id`, { name: FOREIGN_NAME });
    expect(patch.status(), await patch.text()).toBe(200);
    expect(await patch.json(), 'PATCH чужого бизнеса изменил строки').toEqual([]);
  });

  test(`BSET-004: he → en «שמירת שינויים» → PATCH default_language=en, дашборд «פרטי העסק נשמרו»; новая симуляция «שפת הסימולציה» = אנגלית (заблокирована); активные симуляции не меняют язык @desktop @data ${TAG}`, async ({ page }) => {
    const { api, biz } = await openSettings(page);
    const orig = biz.default_language;
    expect(orig, 'исходный язык бизнеса testim должен быть he (вернуть вручную, если остался en после сбоя)').toBe('he');

    const activeBefore = (await (await api.get('simulations?select=id,language&status=eq.active&order=id')).json()) as { id: string; language: string }[];

    try {
      await languageSelect(page).selectOption('en');
      const patchResp = page.waitForResponse((r) => r.url().includes('/rest/v1/businesses') && r.request().method() === 'PATCH');
      await saveButton(page).click();
      const resp = await patchResp;
      // Источник: AC2 «בהינתן שינוי שפת ברירת המחדל של העסק, כאשר אני שומר…» — факт 22.10: PATCH businesses default_language.
      expect(resp.status()).toBeLessThan(300);
      expect(resp.request().postDataJSON()).toMatchObject({ default_language: 'en' });

      // S-06 выход: «שמירה מחזירה לדשבורד עם הפרטים המעודכנים».
      await page.waitForURL((u) => u.pathname === '/');
      const notice = page.getByTestId('settings-saved-notice');
      await expect(notice.getByText('פרטי העסק נשמרו')).toBeVisible();
      await expect(notice).toContainText(biz.name);

      const saved = (await (await api.get(`businesses?select=default_language&id=eq.${biz.id}`)).json()) as { default_language: string }[];
      expect(saved[0]?.default_language).toBe('en');

      // AC2 «סימולציות חדשות נפתחות בשפה החדשה» — форма новой симуляции (без сохранения черновика).
      await page.goto('/simulations/new?start=scratch');
      const simLang = page.locator('#simulation-language');
      await expect(simLang).toBeVisible();
      await expect(simLang).toHaveValue('en');
      await expect(simLang).toBeDisabled();
      await expect(simLang.locator('option:checked')).toHaveText('אנגלית');
      await expect(simLang).toHaveAccessibleDescription('נעולה על שפת ברירת המחדל של העסק.');

      // AC2 «וסימולציות פעילות אינן משתנות».
      const activeAfter = (await (await api.get('simulations?select=id,language&status=eq.active&order=id')).json()) as { id: string; language: string }[];
      expect(activeAfter.filter((s) => activeBefore.some((b) => b.id === s.id))).toEqual(activeBefore);
      test.info().annotations.push({ type: 'active-simulations', description: `активных: ${activeBefore.length}, языки: ${[...new Set(activeBefore.map((s) => s.language))].join(',')}` });
    } finally {
      // Всегда вернуть исходный язык (общий бизнес testim).
      const back = await api.patch(`businesses?id=eq.${biz.id}&select=id,default_language`, { default_language: orig });
      expect(back.status(), `ВЕРНУТЬ ЯЗЫК ВРУЧНУЮ на ${orig}: ${await back.text()}`).toBe(200);
      expect(await back.json()).toEqual([{ id: biz.id, default_language: orig }]);
    }
  });
});
